-- =============================================================================
-- 433 — LE CAHIER D'EXERCICES DE 3E (partie 3)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 433 --niveau 3e --matieres maths --suffixe 3 > supabase/contenu/433_exercices_3e_3.sql
--
-- 84 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   maths.k016              30 exercices · 10 chapitres
--   maths.k017              30 exercices · 10 chapitres
--   maths.k018              24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('643f3e92-e3b3-51bf-8b15-f90682e4d012'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le compteur de points de Maëlle","competence":"programmer","situation":"Maëlle programme un petit jeu sur Scratch. Au départ, son score vaut 2. Elle veut ensuite lui faire gagner 3 points à plusieurs reprises, puis afficher le résultat.","documents":[{"id":"prog","type":"scratch","titre":"Le script de Maëlle","scripts":[[{"categorie":"evenement","texte":"quand le drapeau vert est cliqué"},{"categorie":"variable","texte":"mettre [x] à (2)","id":"z1"},{"categorie":"controle","texte":"répéter (5) fois","id":"z2","interieur":[{"categorie":"variable","texte":"ajouter (3) à [x]","id":"z3"}]},{"categorie":"apparence","texte":"dire (x)","id":"z4"}]]}],"questions":[{"enonce":"Touche le bloc qui est **répété 5 fois**.","aide":"Les blocs à l’intérieur de la boucle sont ceux qui sont « enfermés » dans le crochet du « répéter ».","type":"zone","document":"prog","multiple":false},{"enonce":"Quelle valeur de **x** le lutin dit-il à la fin du programme ?","aide":"Pars de 2 et ajoute 3, cinq fois de suite. Tu peux écrire chaque tour sur ton brouillon.","type":"nombre"},{"enonce":"Combien de fois le bloc « dire x » est-il exécuté ?","aide":"Regarde où se trouve le bloc « dire » : à l’intérieur ou après la boucle ?","type":"choix","options":[{"id":"a","texte":"1 fois"},{"id":"b","texte":"17 fois"},{"id":"c","texte":"5 fois"},{"id":"d","texte":"6 fois"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est **« ajouter 3 à x »** : il est placé à l’intérieur de la boucle, donc répété 5 fois."},{"cle":{"type":"nombre","valeur":17,"tolerance":0},"affichage":"17","explication":"x passe par 2, 5, 8, 11, 14, puis **17** : 2 + 5 × 3 = 17."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le bloc « dire » est placé **après** la boucle : il n’est exécuté qu’**une seule fois**, quand les 5 tours sont terminés."}]$ex$::jsonb),
  ('643f3e92-e3b3-51bf-8b15-f90682e4d012'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le polygone du stylo","competence":"programmer","situation":"Yanis dessine des figures avec le stylo de Scratch. Il a écrit le script ci-dessous : le lutin avance de 40 pas, tourne, et recommence.","documents":[{"id":"prog","type":"scratch","titre":"Le script de Yanis","scripts":[[{"categorie":"evenement","texte":"quand le drapeau vert est cliqué"},{"categorie":"stylo","texte":"stylo en position d’écriture"},{"categorie":"controle","texte":"répéter (6) fois","id":"z1","interieur":[{"categorie":"mouvement","texte":"avancer de (40) pas","id":"z2"},{"categorie":"mouvement","texte":"tourner ↻ de (60) degrés","id":"z3"}]}]]},{"id":"angles","type":"tableau","titre":"L’angle dont tourne le lutin","colonnes":["Figure","Nombre de côtés","Angle de rotation"],"lignes":[["Triangle équilatéral",3,"120°"],["Carré",4,"90°"],["Pentagone régulier",5,"?"],["Hexagone régulier",6,"60°"]],"enteteLignes":true}],"questions":[{"enonce":"Quelle figure le script de Yanis dessine-t-il ?","aide":"Combien de fois la boucle est-elle répétée ? Autant de tours, autant de côtés.","type":"choix","options":[{"id":"a","texte":"Un triangle équilatéral"},{"id":"b","texte":"Un carré"},{"id":"c","texte":"Un pentagone régulier"},{"id":"d","texte":"Un hexagone régulier"}],"multiple":false},{"enonce":"Quelle longueur totale le stylo a-t-il tracée, en pas ?","aide":"Chaque tour de boucle trace un côté de 40 pas.","type":"nombre","unite":"pas"},{"enonce":"Complète le tableau : de quel angle le lutin tourne-t-il pour un **pentagone régulier** ?","aide":"Regarde le carré : 360 ÷ 4 = 90. Même calcul avec 5 côtés.","type":"nombre","unite":"°"},{"enonce":"Pour dessiner un **triangle équilatéral**, que doit changer Yanis dans son script ?","aide":"Un triangle a 3 côtés, et le tableau donne l’angle de rotation pour chaque figure.","type":"choix","options":[{"id":"a","texte":"répéter 3 fois et tourner de 60 degrés"},{"id":"b","texte":"répéter 3 fois et tourner de 120 degrés"},{"id":"c","texte":"répéter 3 fois et avancer de 120 pas"},{"id":"d","texte":"répéter 6 fois et tourner de 120 degrés"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"La boucle se répète 6 fois : le lutin trace 6 côtés égaux avec un angle de 60°, c’est un **hexagone régulier**."},{"cle":{"type":"nombre","valeur":240,"tolerance":0},"affichage":"240 pas","explication":"6 côtés × 40 pas = **240 pas**."},{"cle":{"type":"nombre","valeur":72,"tolerance":0},"affichage":"72 °","explication":"360 ÷ 5 = **72°**. Pour un polygone régulier à n côtés, on tourne de 360 ÷ n."},{"cle":{"type":"choix","ids":["b"]},"explication":"Un triangle a **3 côtés** : la boucle tourne **3 fois**, et le lutin tourne de **120°** à chaque coin (3 × 120° = 360°, un tour complet)."}]$ex$::jsonb),
  ('643f3e92-e3b3-51bf-8b15-f90682e4d012'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le compte à rebours de Lou","competence":"programmer","situation":"Lou programme un compte à rebours sur Scratch. La variable **n** part de 50 et diminue de 8 à chaque tour. La variable **tours** compte les tours de boucle. La boucle s’arrête dès que n devient plus petit que 10.","documents":[{"id":"prog","type":"scratch","titre":"Le script de Lou","scripts":[[{"categorie":"evenement","texte":"quand le drapeau vert est cliqué"},{"categorie":"variable","texte":"mettre [n] à (50)","id":"z1"},{"categorie":"variable","texte":"mettre [tours] à (0)","id":"z2"},{"categorie":"controle","texte":"répéter jusqu’à (n) < (10)","interieur":[{"categorie":"variable","texte":"ajouter (-8) à [n]","id":"z3"},{"categorie":"variable","texte":"ajouter (1) à [tours]","id":"z4"}]},{"categorie":"apparence","texte":"dire (tours)","id":"z5"}]]},{"id":"suivi","type":"tableau","titre":"Le suivi de Lou","colonnes":["Tours effectués","Valeur de n"],"lignes":[["0","50"],["1","42"],["2","?"],["3","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le bloc qui fait **baisser n** à chaque tour.","aide":"Cherche le bloc qui modifie n et qui se trouve à l’intérieur de la boucle.","type":"zone","document":"prog","multiple":false},{"enonce":"Complète le tableau : que vaut **n** après **2 tours** ?","aide":"Pars de 42 et enlève 8.","type":"nombre"},{"enonce":"Combien de **tours** la boucle fait-elle avant de s’arrêter ? C’est ce que dit le lutin.","aide":"Continue la liste : 50, 42, 34, 26… et arrête-toi dès que n est plus petit que 10.","type":"nombre"},{"enonce":"Quelle est la valeur de **n** quand la boucle s’arrête ?","aide":"C’est la première valeur de la liste plus petite que 10.","type":"nombre"},{"enonce":"Lou remplace « ajouter −8 à n » par « ajouter −10 à n ». Que dit maintenant le lutin ?","aide":"Écris la nouvelle liste : 50, 40, 30…","type":"choix","options":[{"id":"a","texte":"La boucle ne s’arrête jamais"},{"id":"b","texte":"6"},{"id":"c","texte":"5"},{"id":"d","texte":"4"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est **« ajouter −8 à n »** : ajouter −8, c’est enlever 8."},{"cle":{"type":"nombre","valeur":34,"tolerance":0},"affichage":"34","explication":"Après 1 tour n vaut 42, après 2 tours **42 − 8 = 34**."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"n prend les valeurs 50, 42, 34, 26, 18, 10, puis **2**. 10 n’est pas plus petit que 10 : il faut encore un tour. La boucle s’arrête après **6 tours**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Après le 6ᵉ tour, n vaut 10 − 8 = **2**, et 2 < 10 : la boucle s’arrête."},{"cle":{"type":"choix","ids":["c"]},"explication":"n prend les valeurs 50, 40, 30, 20, 10, puis **0**, qui est plus petit que 10 : la boucle s’arrête après **5 tours**."}]$ex$::jsonb),
  ('874b9cb5-7eb0-57c0-a140-dccf3249037d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le ballon de hand","competence":"geometrie","situation":"Amel prépare le matériel du club de handball. Elle regarde la fiche technique d’un ballon : son diamètre est de 18 cm. On le modélise par une sphère.","documents":[{"id":"ballon","type":"schema","titre":"Le ballon en coupe","largeur":320,"hauteur":230,"elements":[{"forme":"cercle","cx":160,"cy":115,"r":85,"teinte":"ambre","motif":"clair"},{"forme":"ligne","id":"z1","zone":true,"de":[75,115],"a":[245,115],"fleche":"deux","teinte":"encre"},{"forme":"ligne","id":"z2","zone":true,"de":[160,115],"a":[160,30],"fleche":"fin","teinte":"encre"},{"forme":"cercle","cx":160,"cy":115,"r":3,"teinte":"encre","motif":"plein"},{"forme":"texte","x":172,"y":131,"texte":"O","gras":true},{"forme":"texte","x":205,"y":106,"texte":"18 cm","gras":true,"taille":"petit"}]}],"questions":[{"enonce":"Touche le **rayon** du ballon.","aide":"Le rayon part du centre O et va jusqu’à la surface.","type":"zone","document":"ballon","multiple":false},{"enonce":"Quel est le rayon du ballon ?","aide":"Le rayon est la moitié du diamètre.","type":"nombre","unite":"cm"},{"enonce":"Calcule l’aire de la surface du ballon, **arrondie au dixième** de cm².","aide":"Aire de la sphère : A = 4 × π × R². Utilise le rayon, pas le diamètre !","type":"nombre","unite":"cm²"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le rayon est le segment **du centre O à la surface**. Le diamètre, lui, traverse tout le ballon : c’est le diamètre."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 cm","explication":"18 ÷ 2 = **9 cm**."},{"cle":{"type":"nombre","valeur":1017.9,"tolerance":0.05},"affichage":"1017,9 cm²","explication":"A = 4 × π × 9² = 324π ≈ **1 017,9 cm²**."}]$ex$::jsonb),
  ('874b9cb5-7eb0-57c0-a140-dccf3249037d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Du ping-pong à la pétanque","competence":"calculer","situation":"Au club de loisirs, Noa compare plusieurs boules : la bille, la balle de ping-pong et la boule de pétanque. Il a relevé leur diamètre, mais pas leur rayon.","documents":[{"id":"boules","type":"tableau","titre":"Les boules du club","colonnes":["Objet","Diamètre (cm)","Rayon (cm)"],"lignes":[["Bille",3,1.5],["Balle de ping-pong",4,"?"],["Boule de pétanque",7.5,3.75]],"enteteLignes":true}],"questions":[{"enonce":"Quel est le rayon de la balle de ping-pong (case « ? ») ?","aide":"Regarde comment on passe du diamètre au rayon pour la bille.","type":"nombre","unite":"cm"},{"enonce":"Calcule le volume de la balle de ping-pong, **arrondi au dixième** de cm³.","aide":"Volume de la boule : V = (4/3) × π × R³. Attention au cube : R³ = R × R × R.","type":"nombre","unite":"cm³"},{"enonce":"Calcule le volume de la boule de pétanque, **arrondi à l’unité** de cm³.","aide":"Utilise le rayon 3,75 cm. 3,75³ = 52,734375.","type":"nombre","unite":"cm³"},{"enonce":"Le diamètre de la boule de pétanque est environ 1,9 fois celui de la balle de ping-pong. Son volume est environ…","aide":"Quand les longueurs sont multipliées par k, les volumes sont multipliés par k³. Calcule 1,9³.","type":"choix","options":[{"id":"a","texte":"1,9 fois plus grand"},{"id":"b","texte":"3,6 fois plus grand"},{"id":"c","texte":"6,6 fois plus grand"},{"id":"d","texte":"13 fois plus grand"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 cm","explication":"4 ÷ 2 = **2 cm**."},{"cle":{"type":"nombre","valeur":33.5,"tolerance":0.05},"affichage":"33,5 cm³","explication":"V = (4/3) × π × 2³ = (32/3)π ≈ **33,5 cm³**."},{"cle":{"type":"nombre","valeur":221,"tolerance":0.5},"affichage":"221 cm³","explication":"V = (4/3) × π × 3,75³ ≈ 220,9, soit **221 cm³**."},{"cle":{"type":"choix","ids":["c"]},"explication":"1,9³ ≈ 6,9, et le calcul exact donne 221 ÷ 33,5 ≈ **6,6 fois** : le volume croît beaucoup plus vite que le diamètre."}]$ex$::jsonb),
  ('874b9cb5-7eb0-57c0-a140-dccf3249037d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Trancher la sphère","competence":"modeliser","situation":"Un globe en verre de rayon 13 cm est coupé par un plan situé à 5 cm de son centre O. La coupe fait apparaître un cercle, dont on veut connaître le rayon.","documents":[{"id":"coupe","type":"schema","titre":"La sphère coupée par un plan","largeur":320,"hauteur":240,"elements":[{"forme":"cercle","cx":160,"cy":120,"r":100,"teinte":"bleu","motif":"clair"},{"forme":"ellipse","cx":160,"cy":82,"rx":92,"ry":14,"teinte":"violet","motif":"clair"},{"forme":"ligne","id":"z1","zone":true,"de":[160,120],"a":[160,82],"teinte":"encre"},{"forme":"ligne","id":"z2","zone":true,"de":[160,120],"a":[252,82],"teinte":"encre"},{"forme":"ligne","id":"z3","zone":true,"de":[160,82],"a":[252,82],"teinte":"encre"},{"forme":"cercle","cx":160,"cy":120,"r":3,"teinte":"encre","motif":"plein"},{"forme":"texte","x":172,"y":138,"texte":"O","gras":true},{"forme":"texte","x":155,"y":108,"texte":"d = 5 cm","taille":"petit","ancre":"fin"},{"forme":"texte","x":222,"y":122,"texte":"R = 13 cm","taille":"petit","gras":true},{"forme":"texte","x":208,"y":68,"texte":"r = ?","taille":"petit","gras":true}]}],"questions":[{"enonce":"Touche le segment qui représente la **distance d** entre le centre O et le plan de coupe.","aide":"Cherche le segment vertical : il joint O au centre du cercle de section.","type":"zone","document":"coupe","multiple":false},{"enonce":"Le triangle formé par d, r et R est rectangle. Calcule **r**.","aide":"L’hypoténuse est R (13 cm). Pythagore : r² = R² − d².","type":"nombre","unite":"cm"},{"enonce":"Quelle est l’aire du cercle de section, **arrondie au dixième** de cm² ?","aide":"Aire d’un disque : π × r². Utilise r = 12.","type":"nombre","unite":"cm²"},{"enonce":"Quelle est l’aire de la surface du globe entier, **arrondie au dixième** de cm² ?","aide":"Pour la sphère, c’est R qui compte : A = 4 × π × R².","type":"nombre","unite":"cm²"},{"enonce":"On éloigne le plan jusqu’à d = 12 cm. Quel est alors le rayon du cercle de section ?","aide":"Même triangle rectangle, mais avec d = 12.","type":"nombre","unite":"cm"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La distance d est le segment **vertical** : il est perpendiculaire au plan de coupe."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 cm","explication":"r² = 13² − 5² = 169 − 25 = 144, donc r = **12 cm**."},{"cle":{"type":"nombre","valeur":452.4,"tolerance":0.05},"affichage":"452,4 cm²","explication":"A = π × 12² = 144π ≈ **452,4 cm²**."},{"cle":{"type":"nombre","valeur":2123.7,"tolerance":0.05},"affichage":"2123,7 cm²","explication":"A = 4 × π × 13² = 676π ≈ **2 123,7 cm²**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 cm","explication":"r² = 13² − 12² = 25, donc r = **5 cm** : plus le plan s’éloigne du centre, plus le cercle rétrécit."}]$ex$::jsonb),
  ('c3f57585-0ce4-5223-9fef-6f00e4a3703e'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Trois coups de couteau","competence":"geometrie","situation":"Pour un atelier de cuisine, Sacha tranche une boîte de conserve (un cylindre) et un cône de pâte à modeler. Chaque coupe est représentée par un trait pointillé corail.","documents":[{"id":"solides","type":"schema","titre":"Les trois coupes","largeur":330,"hauteur":170,"elements":[{"forme":"rect","id":"z1","zone":true,"x":25,"y":40,"l":60,"h":70,"teinte":"bleu","motif":"clair"},{"forme":"ellipse","cx":55,"cy":40,"rx":30,"ry":10,"teinte":"bleu","motif":"plein"},{"forme":"ligne","de":[15,75],"a":[95,75],"style":"pointilles","teinte":"corail"},{"forme":"texte","x":55,"y":140,"texte":"A","gras":true,"taille":"grand"},{"forme":"rect","id":"z2","zone":true,"x":135,"y":40,"l":60,"h":70,"teinte":"vert","motif":"clair"},{"forme":"ellipse","cx":165,"cy":40,"rx":30,"ry":10,"teinte":"vert","motif":"plein"},{"forme":"ligne","de":[165,22],"a":[165,122],"style":"pointilles","teinte":"corail"},{"forme":"texte","x":165,"y":140,"texte":"B","gras":true,"taille":"grand"},{"forme":"polygone","id":"z3","zone":true,"points":[[245,115],[305,115],[275,25]],"teinte":"ambre","motif":"clair"},{"forme":"ligne","de":[255,82],"a":[295,82],"style":"pointilles","teinte":"corail"},{"forme":"texte","x":275,"y":140,"texte":"C","gras":true,"taille":"grand"}]}],"questions":[{"enonce":"Touche le solide dont la coupe fait apparaître un **rectangle**.","aide":"Un plan qui contient l’axe d’un cylindre le coupe de haut en bas.","type":"zone","document":"solides","multiple":false},{"enonce":"Associe chaque coupe à la section obtenue.","aide":"Les coupes parallèles à la base donnent un disque ; celle qui contient l’axe donne un rectangle.","type":"association","gauche":[{"id":"g0","texte":"A : cylindre coupé parallèlement à la base"},{"id":"g1","texte":"B : cylindre coupé par un plan contenant l’axe"},{"id":"g2","texte":"C : cône coupé parallèlement à la base"}],"droite":[{"id":"d0","texte":"Un disque plus petit que la base"},{"id":"d1","texte":"Un disque de même rayon"},{"id":"d2","texte":"Un rectangle"}]},{"enonce":"La boîte A a pour rayon 4 cm. Quelle est l’aire de la section de la coupe A, **arrondie au dixième** de cm² ?","aide":"La section A est un disque de rayon 4 cm : aire = π × R².","type":"nombre","unite":"cm²"},{"enonce":"La boîte B mesure 10 cm de haut et a un rayon de 4 cm. Quelle est l’aire de sa section rectangulaire ?","aide":"Le rectangle a pour côtés la hauteur et le diamètre (attention : pas le rayon).","type":"nombre","unite":"cm²"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est le **solide B** : le plan contient l’axe, la section est un rectangle (hauteur × diamètre)."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"A donne un **disque de même rayon**, B un **rectangle**, C un **disque plus petit** que la base (c’est une réduction)."},{"cle":{"type":"nombre","valeur":50.3,"tolerance":0.05},"affichage":"50,3 cm²","explication":"π × 4² = 16π ≈ **50,3 cm²**."},{"cle":{"type":"nombre","valeur":80,"tolerance":0},"affichage":"80 cm²","explication":"Largeur = diamètre = 8 cm ; aire = 8 × 10 = **80 cm²**."}]$ex$::jsonb),
  ('c3f57585-0ce4-5223-9fef-6f00e4a3703e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La pyramide de la maquette","competence":"modeliser","situation":"Pour une maquette, Hugo sculpte une pyramide à base carrée de 12 cm de côté et de hauteur 15 cm. Il la coupe par un plan parallèle à la base, à 6 cm du sommet, et garde le morceau du haut.","documents":[{"id":"pyr","type":"schema","titre":"La pyramide vue de face","largeur":320,"hauteur":230,"elements":[{"forme":"polygone","points":[[160,20],[50,190],[270,190]],"teinte":"violet","motif":"clair"},{"forme":"polygone","id":"z1","zone":true,"points":[[160,20],[116,88],[204,88]],"teinte":"violet","motif":"plein"},{"forme":"ligne","de":[40,88],"a":[280,88],"style":"pointilles","teinte":"corail"},{"forme":"ligne","id":"z2","zone":true,"de":[160,20],"a":[160,88],"fleche":"deux","teinte":"encre"},{"forme":"texte","x":172,"y":58,"texte":"6 cm","taille":"petit","gras":true},{"forme":"texte","x":172,"y":150,"texte":"hauteur : 15 cm","taille":"petit"},{"forme":"texte","x":160,"y":210,"texte":"base carrée de côté 12 cm","taille":"petit"}]}],"questions":[{"enonce":"Touche la hauteur de la **petite pyramide** (celle qu’on garde).","aide":"Elle va du sommet jusqu’au plan de coupe.","type":"zone","document":"pyr","multiple":false},{"enonce":"Quel est le coefficient de réduction k (petite hauteur ÷ grande hauteur) ?","aide":"k = 6 ÷ 15. Tu peux aussi répondre avec la fraction simplifiée.","type":"nombre"},{"enonce":"Quel est le côté du carré de la section ?","aide":"Les longueurs sont multipliées par k.","type":"nombre","unite":"cm"},{"enonce":"Le volume de la grande pyramide est 720 cm³. Quel est le volume de la petite ?","aide":"Les volumes sont multipliés par k³ = 0,4 × 0,4 × 0,4.","type":"nombre","unite":"cm³"}]}$ex$::jsonb,
