  ('652268d5-7b5d-58fa-8a8b-879865addc52'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un triangle qui grandit","competence":"geometrie","situation":"Zoé agrandit un petit triangle ABC en appliquant l’homothétie de centre O et de rapport 2. Les images sont notées A′, B′ et C′. Un carreau mesure 1 cm ; le triangle ABC a pour aire 1 cm².","documents":[{"id":"fig","type":"figure","titre":"Le triangle et son agrandissement","cadre":{"xmin":0,"xmax":9,"ymin":0,"ymax":7},"quadrillage":true,"points":[{"id":"O","x":1,"y":1,"nom":"O","position":"so"},{"id":"A","x":3,"y":1,"nom":"A","position":"s"},{"id":"B","x":3,"y":3,"nom":"B","position":"no"},{"id":"C","x":4,"y":1,"nom":"C","position":"s"},{"id":"A2","x":5,"y":1,"nom":"A′","position":"s"},{"id":"B2","x":5,"y":5,"nom":"B′","position":"no"},{"id":"C2","x":7,"y":1,"nom":"C′","position":"s"}],"segments":[{"de":"O","a":"C2","style":"pointilles","teinte":"gris"},{"de":"O","a":"B2","style":"pointilles","teinte":"gris"}],"polygones":[{"sommets":["A","B","C"],"teinte":"violet","motif":"plein"},{"sommets":["A2","B2","C2"],"teinte":"jaune","motif":"clair"}],"angles":[{"sommet":"A","de":"C","a":"B","droit":true}]}],"questions":[{"enonce":"Touche le point **B′**, l’image de B.","aide":"B′ est sur la demi-droite qui part de O et passe par B, deux fois plus loin de O.","type":"zone","document":"fig","multiple":false},{"enonce":"Le côté [AB] mesure 2 cm. Combien mesure [A′B′] ?","aide":"Les longueurs sont multipliées par le rapport, ici 2.","type":"nombre","unite":"cm"},{"enonce":"Quelle est l’aire du grand triangle A′B′C′ ?","aide":"Les aires sont multipliées par k², pas par k.","type":"nombre","unite":"cm²"},{"enonce":"L’angle en A est droit. Que dire de l’angle en A′ ?","aide":"Une homothétie agrandit sans déformer.","type":"choix","options":[{"id":"a","texte":"On ne peut pas le savoir : l’homothétie déforme les angles"},{"id":"b","texte":"Il mesure 90° : une homothétie conserve la mesure des angles"},{"id":"c","texte":"Il mesure 45° : l’homothétie divise les angles par deux"},{"id":"d","texte":"Il mesure 180° : l’homothétie double les angles"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["B2"]},"explication":"B′ est le sommet du haut du grand triangle : il est sur la droite (OB), à une distance de O **double** de celle de B."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 cm","explication":"2 × 2 = **4 cm**. Tu peux le vérifier en comptant les carreaux."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 cm²","explication":"k² = 2² = 4, donc 1 × 4 = **4 cm²**. Les longueurs doublent, l’aire est multipliée par 4."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’homothétie **conserve les angles** : l’angle en A′ mesure 90°, comme en A."}]$ex$::jsonb),
  ('652268d5-7b5d-58fa-8a8b-879865addc52'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le rapport négatif","competence":"calculer","situation":"Sur une droite graduée, on applique l’homothétie de centre O (le point d’abscisse 0) et de rapport −1,5. Les points A (abscisse 2) et B (abscisse −4) sont déjà placés. Un petit triangle lié à la figure est décrit dans le tableau.","documents":[{"id":"droite","type":"droite","titre":"La droite graduée (centre O en 0)","min":-6,"max":6,"pas":1,"division":2,"points":[{"id":"z1","valeur":2,"nom":"A"},{"id":"z2","valeur":-4,"nom":"B","teinte":"corail"}],"graduationsCliquables":true},{"id":"tab","type":"tableau","titre":"Le triangle MNP avant et après","colonnes":["Grandeur","Avant","Après (rapport −1,5)"],"lignes":[["Côté [MN] (cm)",4,"?"],["Aire (cm²)",10,"?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la graduation où se trouve l’image **A′** de A.","aide":"Multiplie l’abscisse de A par −1,5. Le signe moins envoie A de l’autre côté de O.","type":"zone","document":"droite","multiple":false},{"enonce":"Quelle est l’abscisse de l’image **B′** de B ?","aide":"(−4) × (−1,5) : un moins par un moins donne un plus.","type":"nombre"},{"enonce":"Complète le tableau : que vaut le côté [MN] après l’homothétie ?","aide":"Les longueurs sont multipliées par la valeur absolue du rapport, donc par 1,5.","type":"nombre","unite":"cm"},{"enonce":"Complète le tableau : que vaut l’aire après l’homothétie ?","aide":"Les aires sont multipliées par k² = (−1,5)². Calcule ce carré d’abord.","type":"nombre","unite":"cm²"},{"enonce":"Range chaque propriété : l’homothétie la conserve-t-elle, ou la multiplie-t-elle ?","aide":"Ce qui change, c’est la taille. La forme, elle, ne change pas.","type":"categories","categories":[{"id":"c0","texte":"Conservé"},{"id":"c1","texte":"Multiplié"}],"items":[{"id":"i0","texte":"Les longueurs"},{"id":"i1","texte":"Les angles"},{"id":"i2","texte":"Les aires"},{"id":"i3","texte":"Le parallélisme"},{"id":"i4","texte":"L’alignement des points"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["v-3"]},"explication":"2 × (−1,5) = −3 : **A′ est en −3**, de l’autre côté de O."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"(−4) × (−1,5) = **6** : B était à gauche de O, B′ est à droite."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 cm","explication":"4 × 1,5 = **6 cm** (une longueur n’est jamais négative)."},{"cle":{"type":"nombre","valeur":22.5,"tolerance":0},"affichage":"22,5 cm²","explication":"(−1,5)² = 2,25 et 10 × 2,25 = **22,5 cm²**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Sont **conservés** : alignement, angles, parallélisme. Sont **multipliés** : longueurs (par |k|) et aires (par k²)."}]$ex$::jsonb),
