  ('9cd8e46c-40a0-5394-b760-147c1e8dcf54'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La largeur de l’étang","competence":"modeliser","situation":"Inès veut connaître la largeur AB d’un étang, qu’elle ne peut pas traverser. Elle plante un piquet en O, puis place C et D de l’autre côté pour que A, O, D soient alignés, que B, O, C soient alignés et que (AB) soit parallèle à (CD).","documents":[{"id":"etang","type":"figure","titre":"Le schéma de l’étang (pas à l’échelle des mesures)","cadre":{"xmin":-1,"xmax":11,"ymin":-1,"ymax":9},"quadrillage":false,"points":[{"id":"A","x":0,"y":0,"nom":"A","position":"so"},{"id":"B","x":0,"y":8,"nom":"B","position":"no"},{"id":"O","x":8,"y":4,"nom":"O","position":"n"},{"id":"C","x":10,"y":3,"nom":"C","position":"se"},{"id":"D","x":10,"y":5,"nom":"D","position":"ne"}],"segments":[{"de":"A","a":"O"},{"de":"O","a":"D"},{"de":"B","a":"O"},{"de":"O","a":"C"},{"id":"z1","de":"A","a":"B"},{"id":"z2","de":"C","a":"D"}],"textes":[{"x":3.4,"y":8.3,"texte":"OA = 40 m  ·  OD = 10 m"},{"x":3.4,"y":7.6,"texte":"OC = 7,5 m  ·  CD = 6 m"}]}],"questions":[{"enonce":"Touche les **deux segments parallèles**.","aide":"Relis la situation : quelle droite est parallèle à (CD) ?","type":"zone","document":"etang","multiple":true},{"enonce":"Comment s’appelle cette configuration de Thalès, où A et D (comme B et C) sont de part et d’autre de O ?","aide":"Les deux triangles OAB et ODC se touchent par un sommet, comme les ailes d’un insecte.","type":"choix","options":[{"id":"a","texte":"La pyramide"},{"id":"b","texte":"Le papillon"},{"id":"c","texte":"Le losange"},{"id":"d","texte":"Le triangle emboîté"}],"multiple":false},{"enonce":"Calcule le quotient **OA ÷ OD**.","aide":"OA = 40 m et OD = 10 m.","type":"nombre"},{"enonce":"Calcule **OB**.","aide":"Thalès : OA/OD = OB/OC. Utilise OC = 7,5 m.","type":"nombre","unite":"m"},{"enonce":"Calcule la largeur **AB** de l’étang.","aide":"Thalès : OA/OD = AB/DC, avec DC = 6 m.","type":"nombre","unite":"m"}]}$ex$::jsonb,
