   $ex${"titre":"Les étagères sont-elles droites ?","competence":"raisonner","situation":"Jade monte trois étagères. Pour chacune, les points A, M, B sont alignés dans cet ordre, de même que A, N, C. Elle mesure les longueurs (en cm) et veut vérifier que sa planche [MN] est bien parallèle à [BC].","documents":[{"id":"mesures","type":"tableau","titre":"Les mesures de Jade (en cm)","colonnes":["Étagère","AM","AB","AN","AC"],"lignes":[["E1",3,5,4.5,7.5],["E2",2.4,6,3.5,9],["E3",5,8,7.5,12]],"enteteLignes":true},{"id":"fiche","type":"fiche","modele":"etiquette","entete":"Étagère E3","sousTitre":"Notice de montage","emoji":"📏","teinte":"ambre","lignes":[{"texte":"Planche du bas [BC]","valeur":"20 cm","id":"z1"},{"texte":"Planche du haut [MN]","valeur":"à calculer"}],"pied":"Si (MN) // (BC), on peut utiliser Thalès."}],"questions":[{"enonce":"Pour E1, calcule le quotient **AM ÷ AB**.","aide":"3 ÷ 5.","type":"nombre"},{"enonce":"Pour E2, calcule **AN ÷ AC**, arrondi au millième.","aide":"3,5 ÷ 9. (Pour comparer, AM ÷ AB = 2,4 ÷ 6 = 0,4.)","type":"nombre"},{"enonce":"Range chaque étagère : (MN) est-elle parallèle à (BC) ?","aide":"E3 : calcule 5 ÷ 8 et 7,5 ÷ 12 (ou fais les produits en croix).","type":"categories","categories":[{"id":"c0","texte":"Parallèles"},{"id":"c1","texte":"Pas parallèles"}],"items":[{"id":"i0","texte":"E2"},{"id":"i1","texte":"E3"},{"id":"i2","texte":"E1"}]},{"enonce":"Pour E2, quelle propriété permet de conclure que (MN) n’est pas parallèle à (BC) ?","aide":"Les quotients sont différents : que peut-on déduire pour les droites ?","type":"choix","options":[{"id":"a","texte":"La trigonométrie"},{"id":"b","texte":"La contraposée du théorème de Thalès"},{"id":"c","texte":"Le théorème de Pythagore"},{"id":"d","texte":"La réciproque du théorème de Thalès"}],"multiple":false},{"enonce":"Pour E3, (MN) // (BC). Calcule la longueur de la planche **MN**.","aide":"Thalès : AM/AB = MN/BC, soit 5/8 = MN/20.","type":"nombre","unite":"cm"}]}$ex$::jsonb,
