   $ex${"titre":"Deux triangles en carton","competence":"raisonner","situation":"Lina découpe deux triangles en carton, ABC et DEF. Elle mesure leurs angles, mais certaines valeurs sont encore inconnues. Elle se demande s’ils ont la même forme.","documents":[{"id":"angles","type":"tableau","titre":"Les angles des deux triangles (en degrés)","colonnes":["Triangle","Angle 1","Angle 2","Angle 3"],"lignes":[["ABC (en A, B, C)",40,65,"?"],["DEF (en D, E, F)","?",65,75]],"enteteLignes":true}],"questions":[{"enonce":"Quelle est la mesure de l’angle en **C** ?","aide":"La somme des angles d’un triangle vaut 180°.","type":"nombre","unite":"°"},{"enonce":"Quelle est la mesure de l’angle en **D** ?","aide":"Même méthode : 180° moins les deux autres angles.","type":"nombre","unite":"°"},{"enonce":"Associe chaque sommet de ABC à son **sommet homologue** dans DEF (angles égaux).","aide":"Deux sommets sont homologues quand leurs angles sont égaux.","type":"association","gauche":[{"id":"g0","texte":"A (40°)"},{"id":"g1","texte":"B (65°)"},{"id":"g2","texte":"C (75°)"}],"droite":[{"id":"d0","texte":"F"},{"id":"d1","texte":"E"},{"id":"d2","texte":"D"}]},{"enonce":"Que peut-on conclure ?","aide":"Des angles égaux deux à deux suffisent pour avoir la même forme. Et la taille ?","type":"choix","options":[{"id":"a","texte":"On ne peut rien conclure sans connaître les longueurs des côtés"},{"id":"b","texte":"ABC et DEF ne sont pas semblables : leurs angles sont différents"},{"id":"c","texte":"ABC et DEF sont semblables : leurs angles sont deux à deux égaux"},{"id":"d","texte":"ABC et DEF sont égaux (superposables) : ils ont les mêmes angles"}],"multiple":false}]}$ex$::jsonb,
