  ('00b01cb3-82db-5f4b-80f6-335002a5bffc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux bougies de même forme","competence":"modeliser","situation":"Une chandlerie fabrique deux bougies en forme de pyramide, l’une petite et l’autre grande, semblables l’une à l’autre. Le tableau donne leurs caractéristiques, et l’étiquette la cire utilisée.","documents":[{"id":"bougies","type":"tableau","titre":"Les deux bougies","colonnes":["Bougie","Hauteur (cm)","Aire de la base (cm²)","Volume (cm³)"],"lignes":[["Petite",6,12,24],["Grande",9,"?","?"]],"enteteLignes":true},{"id":"cire","type":"fiche","modele":"etiquette","entete":"Cire de soja","sousTitre":"Fiche du fournisseur","emoji":"🕯️","teinte":"jaune","lignes":[{"texte":"Masse volumique","valeur":"0,9 g/cm³"},{"texte":"Conditionnement","valeur":"sac de 5 kg"}],"pied":"1 cm³ de cire pèse 0,9 g."}],"questions":[{"enonce":"Touche les deux hauteurs qui permettent de calculer le **rapport de similitude k**.","aide":"Il faut deux longueurs homologues : les deux hauteurs.","type":"zone","document":"bougies","multiple":true},{"enonce":"Quel est le rapport k de la petite vers la grande bougie ?","aide":"k = 9 ÷ 6.","type":"nombre"},{"enonce":"Quelle est l’aire de la base de la grande bougie ?","aide":"Une aire est multipliée par k², pas par k.","type":"nombre","unite":"cm²"},{"enonce":"Quel est le volume de la grande bougie ?","aide":"Un volume est multiplié par k³ = 1,5 × 1,5 × 1,5 = 3,375.","type":"nombre","unite":"cm³"},{"enonce":"Quelle masse de cire faut-il pour la grande bougie ?","aide":"Masse = volume × 0,9 g par cm³.","type":"nombre","unite":"g"}]}$ex$::jsonb,
