  ('341af35c-f6ad-5123-91a2-fdc656c6a65c'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Quatre terrains, quatre angles","competence":"raisonner","situation":"Pour tracer des terrains de sport, Lina vérifie avec une corde si les coins sont bien droits. Chaque terrain triangulaire a trois côtés mesurés en mètres, rangés du plus petit au plus grand dans le tableau.","documents":[{"id":"terrains","type":"tableau","titre":"Les côtés des quatre terrains (en m)","colonnes":["Terrain","Côté 1","Côté 2","Côté 3"],"lignes":[["T1",9,12,15],["T2",7,24,25],["T3",8,11,14],["T4",10,24,26]],"enteteLignes":true}],"questions":[{"enonce":"Pour le terrain T2, touche le **plus long côté** : c’est lui qui serait l’hypoténuse.","aide":"Pour la réciproque de Pythagore, on commence par le plus long côté.","type":"zone","document":"terrains","multiple":false},{"enonce":"Pour **T3**, calcule le carré du plus long côté (14²).","aide":"14 × 14.","type":"nombre"},{"enonce":"Pour **T3**, calcule la somme des carrés des deux autres côtés (8² + 11²).","aide":"8² = 64 et 11² = 121.","type":"nombre"},{"enonce":"Que conclure pour T3 ?","aide":"Les deux nombres sont-ils égaux ? S’ils ne le sont pas, que dit la contraposée ?","type":"choix","options":[{"id":"a","texte":"T3 est rectangle parce que 14 est le plus grand côté, donc l’hypoténuse"},{"id":"b","texte":"T3 est rectangle : 196 et 185 sont assez proches, l’écart est négligeable"},{"id":"c","texte":"On ne peut pas conclure avec les longueurs seules : il faut mesurer l’angle"},{"id":"d","texte":"T3 n’est pas rectangle : 196 diffère de 185 (contraposée de Pythagore)"}],"multiple":false},{"enonce":"Range chaque terrain : a-t-il un angle droit ?","aide":"T1 : 81 + 144 ; T2 : 49 + 576 ; T4 : 100 + 576. Compare chaque résultat au carré du plus long côté.","type":"categories","categories":[{"id":"c0","texte":"Rectangle"},{"id":"c1","texte":"Pas rectangle"}],"items":[{"id":"i0","texte":"T2"},{"id":"i1","texte":"T1"},{"id":"i2","texte":"T3"},{"id":"i3","texte":"T4"}]}]}$ex$::jsonb,
