  ('b4bba752-f4ab-521d-bd11-34c41ca92a2b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les deux engrenages","competence":"raisonner","situation":"Deux roues dentées s’engrènent dans une machine. La petite roue a 84 dents et la grande en a 126. On s’intéresse à leur rapport et à leurs tours.","documents":[{"id":"roues","type":"schema","titre":"Les deux roues","largeur":340,"hauteur":200,"elements":[{"forme":"cercle","cx":90,"cy":100,"r":56,"teinte":"ambre","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":232,"cy":100,"r":84,"teinte":"ambre","motif":"clair","id":"z2","zone":true},{"forme":"texte","x":90,"y":104,"texte":"84 dents","ancre":"milieu","gras":true},{"forme":"texte","x":232,"y":104,"texte":"126 dents","ancre":"milieu","gras":true}]}],"questions":[{"enonce":"Touche la roue qui a le **plus de dents**.","aide":"Lis le nombre de dents écrit sur chaque roue.","type":"zone","document":"roues","multiple":false},{"enonce":"Décompose en facteurs premiers.","aide":"84 = 4 × 21 = 4 × 3 × 7. Et 126 = 2 × 63 = 2 × 9 × 7.","type":"trous","segments":["84 = 2² × ",0," × 7     et     126 = 2 × 3² × ",1],"banque":["2","5","3","7"]},{"enonce":"Quel est le **plus grand diviseur commun** de 84 et 126 ?","aide":"Garde les facteurs communs avec le plus petit exposant : 2, 3 et 7.","type":"nombre"},{"enonce":"Quelle est la forme **irréductible** de {{84/126}} ?","aide":"Divise le haut et le bas par 42.","type":"choix","options":[{"id":"a","texte":"{{3/2}}"},{"id":"b","texte":"{{42/63}}"},{"id":"c","texte":"{{2/3}}"},{"id":"d","texte":"{{4/6}}"}],"multiple":false},{"enonce":"Quand la **grande roue** fait 2 tours, combien de tours fait la petite roue ?","aide":"La grande roue a fait passer 2 × 126 dents. Combien de tours de 84 dents cela fait-il ?","type":"nombre","unite":"tours"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La grande roue a **126 dents**."},{"cle":{"type":"trous","trous":[["3"],["7"]]},"affichage":"3 · 7","explication":"84 = 2² × **3** × 7 et 126 = 2 × 3² × **7**."},{"cle":{"type":"nombre","valeur":42,"tolerance":0},"affichage":"42","explication":"Facteurs communs : 2 × 3 × 7 = **42**."},{"cle":{"type":"choix","ids":["c"]},"explication":"84 ÷ 42 = 2 et 126 ÷ 42 = 3 : {{84/126}} = **{{2/3}}**. Les fractions {{42/63}} et {{4/6}} se simplifient encore."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 tours","explication":"2 × 126 = 252 dents, et 252 ÷ 84 = **3 tours**. Le rapport {{84/126}} = {{2/3}} le dit : 2 tours de la grande pour 3 tours de la petite."}]$ex$::jsonb),
  ('cabdf00b-be7a-58b4-94c0-5375b6ebbd9e'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le rectangle de Lina","competence":"modeliser","situation":"Lina dessine un rectangle dont la largeur est x cm et dont la longueur dépasse la largeur de 3 cm.","documents":[{"id":"rect","type":"figure","titre":"Le rectangle (pas à l’échelle)","cadre":{"xmin":-1,"xmax":11,"ymin":-1,"ymax":7},"quadrillage":false,"points":[{"id":"A","x":0,"y":0,"nom":"A","position":"so"},{"id":"B","x":9,"y":0,"nom":"B","position":"se"},{"id":"C","x":9,"y":5,"nom":"C","position":"ne"},{"id":"D","x":0,"y":5,"nom":"D","position":"no"}],"segments":[{"id":"z1","de":"A","a":"B","longueur":"x + 3"},{"id":"z2","de":"B","a":"C","longueur":"x"},{"id":"z3","de":"C","a":"D"},{"id":"z4","de":"D","a":"A"}],"angles":[{"sommet":"A","de":"B","a":"D","droit":true}]}],"questions":[{"enonce":"Touche le côté qui mesure **x + 3**.","aide":"Lis l’étiquette contre chaque côté.","type":"zone","document":"rect","multiple":false},{"enonce":"Quelle expression **réduite** donne le périmètre du rectangle ?","aide":"Périmètre = 2 × (x + 3) + 2 × x. Développe, puis regroupe les termes en x.","type":"choix","options":[{"id":"a","texte":"4x + 6"},{"id":"b","texte":"2x + 6"},{"id":"c","texte":"x² + 3x"},{"id":"d","texte":"4x + 3"}],"multiple":false},{"enonce":"Le périmètre vaut **26 cm**. Résous l’équation 4x + 6 = 26 : que vaut x ?","aide":"Retire 6 des deux côtés, puis divise par 4.","type":"nombre","unite":"cm"},{"enonce":"Avec x = 5, quelle est l’**aire** du rectangle ?","aide":"La longueur vaut 5 + 3 = 8 cm et la largeur 5 cm.","type":"nombre","unite":"cm²"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le côté [AB] est la longueur : **x + 3**."},{"cle":{"type":"choix","ids":["a"]},"explication":"2(x + 3) + 2x = 2x + 6 + 2x = **4x + 6**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 cm","explication":"4x + 6 = 26, donc 4x = 20 et **x = 5**. Vérification : 4 × 5 + 6 = 26."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 cm²","explication":"8 × 5 = **40 cm²**."}]$ex$::jsonb),
  ('cabdf00b-be7a-58b4-94c0-5375b6ebbd9e'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Deux programmes de calcul","competence":"raisonner","situation":"Tom et Zoé testent chacun un programme de calcul à partir du même nombre de départ x. Les deux programmes sont représentés ci-dessous.","documents":[{"id":"progA","type":"chaine","titre":"Le programme de Tom","disposition":"ligne","noeuds":[{"id":"z1","texte":"Nombre x"},{"id":"z2","texte":"× 3"},{"id":"z3","texte":"+ 5"},{"id":"z4","texte":"× 2"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]},{"id":"progB","type":"chaine","titre":"Le programme de Zoé","disposition":"ligne","noeuds":[{"id":"z5","texte":"Nombre x"},{"id":"z6","texte":"+ 7"},{"id":"z7","texte":"× 4"}],"liens":[{"de":"z5","a":"z6"},{"de":"z6","a":"z7"}]}],"questions":[{"enonce":"Quel résultat obtient Tom avec **x = 4** ?","aide":"4 × 3 = 12, puis + 5, puis × 2.","type":"nombre"},{"enonce":"Quelle expression donne le résultat du programme de Tom pour un nombre x ?","aide":"La multiplication par 2 porte sur tout ce qui précède : il faut des parenthèses.","type":"choix","options":[{"id":"a","texte":"2(3x + 5)"},{"id":"b","texte":"2x + 3 + 5"},{"id":"c","texte":"3x + 5 × 2"},{"id":"d","texte":"3(x + 5) × 2"}],"multiple":false},{"enonce":"Tom obtient **52**. Quel nombre de départ a-t-il choisi ?","aide":"Résous 6x + 10 = 52.","type":"nombre"},{"enonce":"Quelle équation traduit : « Tom et Zoé obtiennent **le même résultat** » ? (Le programme de Zoé donne 4(x + 7) = 4x + 28.)","aide":"Écris le résultat de Tom (6x + 10) égal au résultat de Zoé (4x + 28).","type":"choix","options":[{"id":"a","texte":"2(3x + 5) = 4x + 7"},{"id":"b","texte":"3x + 5 = x + 7"},{"id":"c","texte":"6x + 10 = 4x"},{"id":"d","texte":"6x + 10 = 4x + 28"}],"multiple":false},{"enonce":"Résous cette équation : pour quel nombre x les deux programmes donnent-ils le même résultat ?","aide":"Retire 4x et 10 des deux côtés, puis divise par 2.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":34,"tolerance":0},"affichage":"34","explication":"4 × 3 = 12 ; 12 + 5 = 17 ; 17 × 2 = **34**."},{"cle":{"type":"choix","ids":["a"]},"explication":"On multiplie par 3, on ajoute 5, puis on multiplie le tout par 2 : **2(3x + 5)**, soit 6x + 10."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7","explication":"6x + 10 = 52, donc 6x = 42 et **x = 7**. Vérification : (7 × 3 + 5) × 2 = 52."},{"cle":{"type":"choix","ids":["d"]},"explication":"Tom : 2(3x + 5) = 6x + 10. Zoé : 4(x + 7) = 4x + 28. On écrit donc **6x + 10 = 4x + 28**."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"6x + 10 = 4x + 28, donc 2x = 18 et **x = 9**. Vérification : Tom obtient 64 et Zoé 4 × 16 = 64."}]$ex$::jsonb),
  ('cabdf00b-be7a-58b4-94c0-5375b6ebbd9e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’allée du jardin","competence":"modeliser","situation":"Jade aménage son jardin : une pelouse carrée de côté x (en m), entourée d’une allée de 1 m de large. Elle note dans un tableau l’aire de l’allée pour quelques valeurs de x.","documents":[{"id":"jardin","type":"schema","titre":"Le jardin (vu de dessus)","largeur":320,"hauteur":240,"elements":[{"forme":"rect","x":40,"y":20,"l":200,"h":200,"teinte":"sable","motif":"clair","id":"z1","zone":true},{"forme":"rect","x":70,"y":50,"l":140,"h":140,"teinte":"vert","motif":"clair","id":"z2","zone":true},{"forme":"texte","x":140,"y":38,"texte":"1 m","ancre":"milieu","taille":"petit"},{"forme":"texte","x":140,"y":125,"texte":"Pelouse","ancre":"milieu","gras":true},{"forme":"texte","x":140,"y":145,"texte":"côté x","ancre":"milieu","taille":"petit"}]},{"id":"essais","type":"tableau","titre":"Les essais de Jade","colonnes":["x (en m)","5","10","15","20"],"lignes":[["Aire de l’allée (en m²)",24,44,64,84]],"enteteLignes":true}],"questions":[{"enonce":"Touche la **pelouse**.","aide":"La pelouse est au centre, entourée par l’allée.","type":"zone","document":"jardin","multiple":false},{"enonce":"Quelle expression donne l’aire de l’**allée** ?","aide":"Le grand carré a pour côté x + 1 + 1. Retire l’aire de la pelouse.","type":"choix","options":[{"id":"a","texte":"4 × (x + 2)"},{"id":"b","texte":"x² − (x + 2)²"},{"id":"c","texte":"(x + 2)² − x²"},{"id":"d","texte":"(x + 1)² − x²"}],"multiple":false},{"enonce":"Développe et réduis : (x + 2)² − x² = ___ x + 4. Quel est le coefficient de x ?","aide":"(x + 2)² = x² + 4x + 4. Puis retire x².","type":"nombre"},{"enonce":"L’allée a une aire de **60 m²**. Résous 4x + 4 = 60 : que vaut x ?","aide":"Retire 4 des deux côtés puis divise par 4. Le tableau montre que x est entre 10 et 15.","type":"nombre","unite":"m"},{"enonce":"Quelle est alors l’aire de la **pelouse** ?","aide":"La pelouse est un carré de côté x = 14 m.","type":"nombre","unite":"m²"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La **pelouse** est le carré central, de côté x."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le grand carré (pelouse + allée) a pour côté x + 2. L’aire de l’allée est l’aire du grand carré moins celle de la pelouse : **(x + 2)² − x²**."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"(x + 2)² − x² = x² + 4x + 4 − x² = **4x** + 4. L’aire de l’allée vaut 4x + 4."},{"cle":{"type":"nombre","valeur":14,"tolerance":0},"affichage":"14 m","explication":"4x + 4 = 60, donc 4x = 56 et **x = 14**. Cohérent avec le tableau : 44 (x = 10) < 60 < 64 (x = 15)."},{"cle":{"type":"nombre","valeur":196,"tolerance":0},"affichage":"196 m²","explication":"14² = **196 m²**."}]$ex$::jsonb),
  ('6ce27644-5fff-5750-aa4a-a35d8918c0dd'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le carré de Mia","competence":"geometrie","situation":"Mia découpe un carré de côté x + 3 (en cm) en quatre morceaux, comme sur le schéma.","documents":[{"id":"carre","type":"schema","titre":"Le carré découpé","largeur":280,"hauteur":250,"elements":[{"forme":"rect","x":40,"y":30,"l":130,"h":130,"teinte":"violet","motif":"clair","id":"z1","zone":true},{"forme":"rect","x":170,"y":30,"l":60,"h":130,"teinte":"violet","motif":"clair","id":"z2","zone":true},{"forme":"rect","x":40,"y":160,"l":130,"h":60,"teinte":"violet","motif":"clair","id":"z3","zone":true},{"forme":"rect","x":170,"y":160,"l":60,"h":60,"teinte":"violet","motif":"clair","id":"z4","zone":true},{"forme":"texte","x":105,"y":22,"texte":"x","ancre":"milieu"},{"forme":"texte","x":200,"y":22,"texte":"3","ancre":"milieu"},{"forme":"texte","x":24,"y":100,"texte":"x","ancre":"milieu"},{"forme":"texte","x":24,"y":195,"texte":"3","ancre":"milieu"},{"forme":"texte","x":105,"y":100,"texte":"x²","ancre":"milieu","gras":true},{"forme":"texte","x":200,"y":100,"texte":"3x","ancre":"milieu","gras":true},{"forme":"texte","x":105,"y":195,"texte":"3x","ancre":"milieu","gras":true},{"forme":"texte","x":200,"y":195,"texte":"9","ancre":"milieu","gras":true}]}],"questions":[{"enonce":"Touche le **petit carré**, d’aire 9 cm².","aide":"Il a 3 cm de côté : 3 × 3 = 9.","type":"zone","document":"carre","multiple":false},{"enonce":"Touche les **deux rectangles** qui ont la même aire 3x.","aide":"Ils mesurent 3 cm sur x cm.","type":"zone","document":"carre","multiple":true},{"enonce":"En additionnant les aires des quatre morceaux, que vaut (x + 3)² développé ?","aide":"x² + 3x + 3x + 9. Regroupe les deux rectangles.","type":"choix","options":[{"id":"a","texte":"x² + 6x + 9"},{"id":"b","texte":"x² + 9"},{"id":"c","texte":"2x + 6"},{"id":"d","texte":"x² + 3x + 9"}],"multiple":false},{"enonce":"Pour x = 5, quelle est l’aire du grand carré de côté x + 3 ?","aide":"Le côté vaut 5 + 3 = 8 cm.","type":"nombre","unite":"cm²"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"Le petit carré est celui de côté 3 cm : son aire vaut **9 cm²**."},{"cle":{"type":"zone","ids":["z2","z3"]},"explication":"Les deux rectangles de dimensions 3 et x ont chacun une aire de **3x**."},{"cle":{"type":"choix","ids":["a"]},"explication":"x² + 3x + 3x + 9 = **x² + 6x + 9**. Le double produit 2 × x × 3 = 6x vient des deux rectangles."},{"cle":{"type":"nombre","valeur":64,"tolerance":0},"affichage":"64 cm²","explication":"8² = **64 cm²**. Avec la formule : 25 + 30 + 9 = 64."}]$ex$::jsonb),
  ('6ce27644-5fff-5750-aa4a-a35d8918c0dd'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le calcul mental de Noa","competence":"calculer","situation":"Noa calcule de tête des carrés et des produits qui semblent difficiles. Ali lui demande son secret par SMS.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Le SMS d’Ali","participants":[{"nom":"Ali","emoji":"👦","cote":"gauche"},{"nom":"Noa","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Ali","texte":"Comment tu as trouvé 102² = 10 404 sans calculatrice ?"},{"qui":"Noa","texte":"J’ai écrit 102 = 100 + 2, puis j’ai utilisé une identité remarquable !"},{"qui":"Ali","texte":"Et pour 59 × 61, ça marche aussi ?"},{"qui":"Noa","texte":"Oui : 59 = 60 − 1 et 61 = 60 + 1."}]}],"questions":[{"enonce":"Touche les deux mots qui nomment l’**outil** utilisé par Noa.","aide":"Cherche, dans le premier message de Noa, le nom de la méthode.","type":"zone","document":"sms","multiple":true},{"enonce":"Quelle écriture correspond à la méthode de Noa pour 102² ?","aide":"Pense à (a + b)² = a² + 2ab + b² avec a = 100 et b = 2.","type":"choix","options":[{"id":"a","texte":"(100 + 2)² = 100² + 2 × 100 × 2 + 2²"},{"id":"b","texte":"(100 + 2)² = 100² + 2²"},{"id":"c","texte":"(100 − 2)² = 100² − 2 × 100 × 2 + 2², qui donne 98²"},{"id":"d","texte":"102² = 100 × 2"}],"multiple":false},{"enonce":"Calcule **59 × 61** de tête, avec l’astuce de Noa.","aide":"C’est (60 − 1)(60 + 1) : une différence de deux carrés.","type":"nombre"},{"enonce":"Calcule **98²** en complétant.","aide":"98 = 100 − 2. Le double produit vaut 2 × 100 × 2.","type":"trous","segments":["98² = (100 − ",0,")² = 10 000 − ",1," + 4"],"banque":["400","2","4","200"]},{"enonce":"Noa propose maintenant **998²**. Que trouve-t-elle ?","aide":"998 = 1 000 − 2. Le double produit vaut 2 × 1 000 × 2 = 4 000.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20","m21"]},"explication":"Noa utilise une **identité remarquable**."},{"cle":{"type":"choix","ids":["a"]},"explication":"(100 + 2)² = 10 000 + 400 + 4 = **10 404**. Sans le double produit 2 × 100 × 2 = 400, on se tromperait."},{"cle":{"type":"nombre","valeur":3599,"tolerance":0},"affichage":"3599","explication":"(60 − 1)(60 + 1) = 60² − 1² = 3 600 − 1 = **3 599**."},{"cle":{"type":"trous","trous":[["2"],["400"]]},"affichage":"2 · 400","explication":"98² = (100 − **2**)² = 10 000 − **400** + 4 = 9 604."},{"cle":{"type":"nombre","valeur":996004,"tolerance":0},"affichage":"996 004","explication":"(1 000 − 2)² = 1 000 000 − 4 000 + 4 = **996 004**."}]$ex$::jsonb),
  ('6ce27644-5fff-5750-aa4a-a35d8918c0dd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le tour de magie de Tom","competence":"raisonner","situation":"Tom présente un tour de magie à sa classe : « Quel que soit le nombre que vous choisissez, je devine le résultat de mon programme ! » Il a testé trois nombres.","documents":[{"id":"programme","type":"texte","genre":"consigne","titre":"Le programme de Tom","blocs":["Choisis un nombre x.","Ajoute-lui 3.","Retire 3 au nombre de départ.","Multiplie les deux résultats obtenus.","Ajoute 9."]},{"id":"essais","type":"tableau","titre":"Les essais de Tom","colonnes":["Nombre choisi","2","5","10"],"lignes":[["Résultat",4,25,100]],"enteteLignes":true}],"questions":[{"enonce":"Applique le programme à **x = 6**. Quel résultat obtiens-tu ?","aide":"6 + 3 = 9 ; 6 − 3 = 3 ; 9 × 3 = 27 ; puis ajoute 9.","type":"nombre"},{"enonce":"Range les étapes d’une **démonstration** pour un nombre x quelconque.","aide":"On commence par nommer le nombre, puis on traduit, on calcule, et on conclut.","type":"ordre","items":[{"id":"a","texte":"On appelle x le nombre de départ"},{"id":"b","texte":"On conclut : le résultat est toujours x²"},{"id":"c","texte":"On traduit le programme : (x + 3)(x − 3) + 9"},{"id":"d","texte":"On développe : x² − 9 + 9"}]},{"enonce":"Teste **x = −7**. Quel résultat Tom devine-t-il ?","aide":"−7 + 3 = −4 ; −7 − 3 = −10 ; le produit de deux nombres négatifs est positif.","type":"nombre"},{"enonce":"Pourquoi les trois essais du tableau ne **prouvent-ils pas** que le résultat est toujours x² ?","aide":"Que se passerait-il avec un quatrième nombre ? Seule la lettre x couvre tous les cas.","type":"choix","options":[{"id":"a","texte":"Parce que le nombre 2 est pair, donc il ne convient pas aux essais"},{"id":"b","texte":"Parce que le tableau n’a que trois colonnes et qu’il en faudrait dix"},{"id":"c","texte":"Parce que le nombre 10 est trop grand pour servir d’essai valable"},{"id":"d","texte":"Trois exemples ne prouvent rien : il faut un calcul avec une lettre"}],"multiple":false},{"enonce":"Tom invente un second programme, qui donne (x + 3)² − 9. Quelle est sa forme **factorisée** ?","aide":"(x + 3)² − 9 = (x + 3)² − 3² : différence de deux carrés (a − b)(a + b), avec a = x + 3 et b = 3.","type":"choix","options":[{"id":"a","texte":"x² + 6x + 18"},{"id":"b","texte":"(x + 6)²"},{"id":"c","texte":"(x − 3)(x + 3)"},{"id":"d","texte":"x(x + 6)"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36","explication":"9 × 3 = 27, puis 27 + 9 = **36**."},{"cle":{"type":"ordre","ids":["a","c","d","b"]},"explication":"Démonstration : x, puis (x + 3)(x − 3) + 9 = x² − 9 + 9 = **x²**. (x + 3)(x − 3) est l’identité (a + b)(a − b) = a² − b²."},{"cle":{"type":"nombre","valeur":49,"tolerance":0},"affichage":"49","explication":"(−4) × (−10) = 40, puis 40 + 9 = **49** = (−7)². Le résultat est bien x²."},{"cle":{"type":"choix","ids":["d"]},"explication":"Tester quelques nombres n’est qu’une **conjecture**. Seul le calcul littéral, avec une lettre, démontre un résultat pour tous les nombres."},{"cle":{"type":"choix","ids":["d"]},"explication":"(x + 3)² − 3² = (x + 3 − 3)(x + 3 + 3) = **x(x + 6)**. On retrouve x² + 6x en développant."}]$ex$::jsonb),
  ('2da8ba73-e59b-5e4b-8716-85dfaa3c8613'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Sur la droite graduée","competence":"raisonner","situation":"Amel repère des solutions d’équations et d’inéquations sur une droite graduée. Touche les graduations qui conviennent.","documents":[{"id":"droite","type":"droite","titre":"La droite graduée","min":-5,"max":5,"pas":1,"division":1,"graduationsCliquables":true}],"questions":[{"enonce":"Touche les **deux solutions** de l’équation (x − 2)(x + 3) = 0.","aide":"Un produit est nul si l’un de ses facteurs est nul : x − 2 = 0 ou x + 3 = 0.","type":"zone","document":"droite","multiple":true},{"enonce":"Touche la solution **non nulle** de l’équation x(x − 4) = 0.","aide":"x = 0 ou x − 4 = 0.","type":"zone","document":"droite","multiple":false},{"enonce":"Touche tous les **nombres entiers** de la droite qui vérifient l’inéquation x ≤ −3.","aide":"« ≤ » veut dire « plus petit ou égal » : −3 est inclus.","type":"zone","document":"droite","multiple":true},{"enonce":"Résous 2x − 1 < 7. Quel est le **plus grand entier** solution ?","aide":"Ajoute 1 des deux côtés puis divise par 2 : x < ... Le nombre trouvé est-il inclus ?","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["v2","v-3"]},"explication":"x − 2 = 0 donne **x = 2** et x + 3 = 0 donne **x = −3**."},{"cle":{"type":"zone","ids":["v4"]},"explication":"x(x − 4) = 0 donne x = 0 ou **x = 4**. La solution non nulle est 4."},{"cle":{"type":"zone","ids":["v-5","v-4","v-3"]},"explication":"Les entiers inférieurs ou égaux à −3, sur cette droite, sont **−5, −4 et −3**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"2x < 8 donc x < 4. Le nombre 4 est exclu : le plus grand entier solution est **3**."}]$ex$::jsonb),
  ('2da8ba73-e59b-5e4b-8716-85dfaa3c8613'::uuid, 2, 2, 10, 35, 5,
