nonce":"Un élève de 6e de plus s’inscrit (73 élèves de 6e). Peut-on encore former 36 équipes identiques ?","aide":"36 est-il un diviseur de 73 ? Fais la division euclidienne.","type":"choix","options":[{"id":"a","texte":"Oui : 73 est proche de 72, donc on peut arrondir"},{"id":"b","texte":"Non : 73 n’est pas divisible par 36, car 73 = 2 × 36 + 1"},{"id":"c","texte":"Oui : 73 est un nombre premier, donc on peut le partager"},{"id":"d","texte":"Non : 73 est un nombre pair, donc impossible à répartir"}],"multiple":false}]}$ex$::jsonb,
